#include "workspace.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>
static uint32_t u32(const uint8_t *p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint64_t u64(const uint8_t *p){return u32(p)|(uint64_t)u32(p+4)<<32;}
static void put32(uint8_t *p,uint32_t v){for(int i=0;i<4;i++)p[i]=(uint8_t)(v>>(i*8));}
static void put64(uint8_t *p,uint64_t v){put32(p,(uint32_t)v);put32(p+4,(uint32_t)(v>>32));}
static uint64_t checksum(const uint8_t *p,size_t n){uint64_t h=14695981039346656037ull;for(size_t i=0;i<n;i++){h^=p[i];h*=1099511628211ull;}return h;}
static int stopped(HANDLE h){return h&&WaitForSingleObject(h,0)==WAIT_OBJECT_0;}
void workspace_free(workspace_catalog *c){for(uint32_t i=0;i<c->count&&i<WS_MAX;i++)session_free(&c->items[i].snapshot);memset(c,0,sizeof *c);}
int workspace_name(const wchar_t *input,wchar_t out[WS_NAME]){if(!input)return 0;size_t n=wcslen(input);if(!n||n>=WS_NAME||input[0]==' '||input[n-1]==' ')return 0;for(size_t i=0;i<n;i++){uint16_t ch=(uint16_t)input[i];if(ch<32||ch==127)return 0;if(ch>=0xd800&&ch<=0xdbff){if(++i>=n||input[i]<0xdc00||input[i]>0xdfff)return 0;}else if(ch>=0xdc00&&ch<=0xdfff)return 0;}memcpy(out,input,(n+1)*2);return 1;}
int workspace_snapshot_valid(const session *s){if(!s||s->has_rect||s->maximized||s->npins||s->nrecent||s->tree<0||s->tree>1||s->dual<0||s->dual>1||s->hidden<0||s->hidden>1||s->active<0||s->active>1||(!s->dual&&s->active)||s->tree_w<120||s->tree_w>1200||!isfinite(s->ratio)||s->ratio<.15||s->ratio>.85)return 0;
 for(int p=0;p<2;p++){if(s->ntabs[p]<1||s->ntabs[p]>SES_TABS_MAX||s->cur[p]<0||s->cur[p]>=s->ntabs[p])return 0;for(int i=0;i<s->ntabs[p];i++){const ses_tab *t=&s->tabs[p][i];if(!t->path||!*t->path||wcslen(t->path)>=32768||t->sort>4||t->desc>1)return 0;const wchar_t *v=t->path;if(!((v[0]&&v[1]==':'&&v[2]=='\\')||(v[0]=='\\'&&v[1]=='\\')))return 0;}}
 return 1;
}
DWORD workspace_clone(const session *s,session *out){session_defaults(out);if(!workspace_snapshot_valid(s))return ERROR_INVALID_DATA;out->tree=s->tree;out->dual=s->dual;out->hidden=s->hidden;out->active=s->active;out->tree_w=s->tree_w;out->ratio=s->ratio;
 for(int p=0;p<2;p++){out->cur[p]=s->cur[p];for(int i=0;i<s->ntabs[p];i++){ses_tab *t=&out->tabs[p][i];*t=s->tabs[p][i];t->path=_wcsdup(t->path);out->ntabs[p]++;if(!t->path){session_free(out);return ERROR_NOT_ENOUGH_MEMORY;}}}return 0;}
int workspace_find(const workspace_catalog *c,const wchar_t *name){for(uint32_t i=0;i<c->count;i++)if(!_wcsicmp(c->items[i].name,name))return (int)i;return -1;}
DWORD workspace_format(const workspace_catalog *c,uint8_t **data,size_t *bytes){*data=NULL;*bytes=0;if(c->count>WS_MAX)return ERROR_INVALID_DATA;uint8_t *out=malloc(WS_FILE_MAX);char *text=malloc(WS_SNAPSHOT_MAX);if(!out||!text){free(out);free(text);return ERROR_NOT_ENOUGH_MEMORY;}size_t at=32;DWORD error=0;
 for(uint32_t i=0;i<c->count;i++){wchar_t name[WS_NAME];if(!workspace_name(c->items[i].name,name)||!workspace_snapshot_valid(&c->items[i].snapshot)||workspace_find(c,name)!=(int)i){error=ERROR_INVALID_DATA;break;}size_t n=wcslen(name);size_t len=session_format(&c->items[i].snapshot,text,WS_SNAPSHOT_MAX);if(!len||at+8+n*2+len>WS_FILE_MAX){error=ERROR_BUFFER_OVERFLOW;break;}put32(out+at,(uint32_t)n);put32(out+at+4,(uint32_t)len);at+=8;for(size_t j=0;j<n;j++){out[at++]=(uint8_t)name[j];out[at++]=(uint8_t)(name[j]>>8);}memcpy(out+at,text,len);at+=len;}
 free(text);if(error){free(out);return error;}memcpy(out,"OPWS0001",8);put32(out+8,(uint32_t)at);put32(out+12,c->count);put64(out+16,c->revision);put64(out+24,checksum(out+32,at-32));*data=out;*bytes=at;return 0;
}
DWORD workspace_parse(const uint8_t *data,size_t bytes,workspace_catalog *c){if(bytes<32||bytes>WS_FILE_MAX||memcmp(data,"OPWS0001",8)||u32(data+8)!=bytes||u32(data+12)>WS_MAX||u64(data+24)!=checksum(data+32,bytes-32))return ERROR_INVALID_DATA;
 workspace_catalog *next=calloc(1,sizeof *next);char *text=malloc(WS_SNAPSHOT_MAX);if(!next||!text){free(next);free(text);return ERROR_NOT_ENOUGH_MEMORY;}next->revision=u64(data+16);size_t at=32;DWORD error=0;
 for(uint32_t i=0;i<u32(data+12);i++){if(bytes-at<8){error=ERROR_INVALID_DATA;break;}uint32_t n=u32(data+at),len=u32(data+at+4);at+=8;if(!n||n>=WS_NAME||!len||len>=WS_SNAPSHOT_MAX||bytes-at<(size_t)n*2+len){error=ERROR_INVALID_DATA;break;}wchar_t name[WS_NAME];for(uint32_t j=0;j<n;j++){name[j]=(wchar_t)(data[at]|data[at+1]<<8);at+=2;}name[n]=0;wchar_t valid[WS_NAME];if(wcslen(name)!=n||!workspace_name(name,valid)||workspace_find(next,name)>=0||memchr(data+at,0,len)){error=ERROR_INVALID_DATA;break;}
  workspace *w=&next->items[next->count++];wcscpy(w->name,name);session_parse((const char*)data+at,len,&w->snapshot);size_t canonical=session_format(&w->snapshot,text,WS_SNAPSHOT_MAX);if(!workspace_snapshot_valid(&w->snapshot)||canonical!=len||memcmp(text,data+at,len)){error=ERROR_INVALID_DATA;break;}at+=len;}
 if(!error&&at!=bytes)error=ERROR_INVALID_DATA;free(text);if(!error){workspace_free(c);*c=*next;memset(next,0,sizeof *next);}workspace_free(next);free(next);return error;
}
DWORD workspace_load(const wchar_t *file,workspace_catalog *out,HANDLE cancel){if(stopped(cancel))return ERROR_CANCELLED;HANDLE f=CreateFileW(file,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_DELETE,NULL,OPEN_EXISTING,FILE_FLAG_SEQUENTIAL_SCAN|FILE_FLAG_OPEN_REPARSE_POINT,NULL);if(f==INVALID_HANDLE_VALUE){DWORD e=GetLastError();if(e==ERROR_FILE_NOT_FOUND||e==ERROR_PATH_NOT_FOUND){workspace_free(out);return 0;}return e;}DWORD error=0;LARGE_INTEGER size;BY_HANDLE_FILE_INFORMATION info;uint8_t *data=NULL;
 if(!GetFileInformationByHandle(f,&info)||!GetFileSizeEx(f,&size)){error=GetLastError();goto done;}if(GetFileType(f)!=FILE_TYPE_DISK||info.dwFileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)||size.QuadPart<32||size.QuadPart>WS_FILE_MAX){error=ERROR_INVALID_DATA;goto done;}
 data=malloc((size_t)size.QuadPart);if(!data){error=ERROR_NOT_ENOUGH_MEMORY;goto done;}for(DWORD at=0;at<(DWORD)size.QuadPart;){if(stopped(cancel)){error=ERROR_CANCELLED;goto done;}DWORD got=0,want=(DWORD)size.QuadPart-at;if(want>65536)want=65536;if(!ReadFile(f,data+at,want,&got,NULL)){error=GetLastError();goto done;}if(!got){error=ERROR_HANDLE_EOF;goto done;}at+=got;}if(stopped(cancel)){error=ERROR_CANCELLED;goto done;}error=workspace_parse(data,(size_t)size.QuadPart,out);
done:free(data);CloseHandle(f);return error;
}
DWORD workspace_change(const wchar_t *file,uint64_t expected,uint32_t action,const wchar_t *name,const wchar_t *new_name,const session *snapshot,workspace_catalog *out,HANDLE cancel){wchar_t normalized[WS_NAME],renamed[WS_NAME];if(!file||!*file||!workspace_name(name,normalized)||action<WS_CREATE||action>WS_DELETE||(action==WS_RENAME&&!workspace_name(new_name,renamed)))return ERROR_INVALID_PARAMETER;
 if(stopped(cancel))return ERROR_CANCELLED;size_t count=wcslen(file);wchar_t *lockpath=malloc((count+8)*2),*tmp=malloc((count+80)*2),*parent=_wcsdup(file);workspace_catalog *next=calloc(1,sizeof *next);HANDLE lock=INVALID_HANDLE_VALUE,writer=INVALID_HANDLE_VALUE;uint8_t *data=NULL;size_t bytes=0;DWORD error=0;int owned=0;
 if(!lockpath||!tmp||!parent||!next){error=ERROR_NOT_ENOUGH_MEMORY;goto done;}wchar_t *slash=wcsrchr(parent,L'\\');if(slash){*slash=0;if(!CreateDirectoryW(parent,NULL)&&GetLastError()!=ERROR_ALREADY_EXISTS){error=GetLastError();goto done;}}
 swprintf(lockpath,count+8,L"%ls.lock",file);lock=CreateFileW(lockpath,GENERIC_READ|GENERIC_WRITE,0,NULL,OPEN_ALWAYS,FILE_ATTRIBUTE_HIDDEN|FILE_FLAG_DELETE_ON_CLOSE|FILE_FLAG_OPEN_REPARSE_POINT,NULL);if(lock==INVALID_HANDLE_VALUE){error=GetLastError();goto done;}
 BY_HANDLE_FILE_INFORMATION lockinfo;if(!GetFileInformationByHandle(lock,&lockinfo)){error=GetLastError();goto done;}if(lockinfo.dwFileAttributes&(FILE_ATTRIBUTE_REPARSE_POINT|FILE_ATTRIBUTE_DIRECTORY)){error=ERROR_INVALID_DATA;goto done;}
 error=workspace_load(file,next,cancel);if(error)goto done;if(next->revision!=expected){error=ERROR_REVISION_MISMATCH;goto done;}int index=workspace_find(next,normalized);
 if(action==WS_CREATE){if(index>=0){error=ERROR_ALREADY_EXISTS;goto done;}if(next->count==WS_MAX){error=ERROR_TOO_MANY_NAMES;goto done;}workspace *w=&next->items[next->count];error=workspace_clone(snapshot,&w->snapshot);if(error)goto done;wcscpy(w->name,normalized);next->count++;}
 else{if(index<0){error=ERROR_NOT_FOUND;goto done;}workspace *w=&next->items[index];if(action==WS_UPDATE){session fresh;error=workspace_clone(snapshot,&fresh);if(error)goto done;session_free(&w->snapshot);w->snapshot=fresh;}else if(action==WS_RENAME){int other=workspace_find(next,renamed);if(other>=0&&other!=index){error=ERROR_ALREADY_EXISTS;goto done;}wcscpy(w->name,renamed);}else{session_free(&w->snapshot);memmove(w,w+1,(next->count-(uint32_t)index-1)*sizeof *w);memset(&next->items[--next->count],0,sizeof *w);}}
 if(next->revision==UINT64_MAX){error=ERROR_ARITHMETIC_OVERFLOW;goto done;}next->revision++;error=workspace_format(next,&data,&bytes);if(error)goto done;if(stopped(cancel)){error=ERROR_CANCELLED;goto done;}
 swprintf(tmp,count+80,L"%ls.%lu.%llu.tmp",file,(unsigned long)GetCurrentProcessId(),(unsigned long long)GetTickCount64());writer=CreateFileW(tmp,GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,NULL);if(writer==INVALID_HANDLE_VALUE){error=GetLastError();goto done;}owned=1;for(DWORD at=0;at<(DWORD)bytes;){if(stopped(cancel)){error=ERROR_CANCELLED;goto done;}DWORD wrote=0,want=(DWORD)bytes-at;if(want>65536)want=65536;if(!WriteFile(writer,data+at,want,&wrote,NULL)){error=GetLastError();goto done;}if(!wrote){error=ERROR_WRITE_FAULT;goto done;}at+=wrote;}
 if(!FlushFileBuffers(writer)){error=GetLastError();goto done;}CloseHandle(writer);writer=INVALID_HANDLE_VALUE;if(stopped(cancel)){error=ERROR_CANCELLED;goto done;}if(!MoveFileExW(tmp,file,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){error=GetLastError();goto done;}owned=0;workspace_free(out);*out=*next;memset(next,0,sizeof *next);
done:if(writer!=INVALID_HANDLE_VALUE)CloseHandle(writer);if(owned)DeleteFileW(tmp);if(lock!=INVALID_HANDLE_VALUE)CloseHandle(lock);free(data);free(lockpath);free(tmp);free(parent);if(next){workspace_free(next);free(next);}return error;
}
